(() => {
'use strict';
const steps=[
{title:'Start with what the page shows.',label:'01 / Observation',heading:'The public pricing page is the next useful place.',summary:'The example starts on a fictional product homepage. Its navigation contains a Pricing link. No price has been found yet.',beforeLabel:'Page observation',before:'A navigation link labeled Pricing is visible on the fictional homepage.',afterLabel:'Boundary',after:'Read public pages. Do not submit forms or make purchases.'},
{title:'Make the next move inspectable.',label:'02 / Proposed action',heading:'Open the Pricing link. Nothing more.',summary:'The proposed action stays inside the task: inspect public pricing. The runtime would check that action against the run’s policy before execution.',beforeLabel:'Proposed browser action',before:'Click the observed Pricing link on this page.',afterLabel:'Policy check',after:'Public navigation only. No form submission, account change or purchase is proposed.'},
{title:'Separate a proposal from an executed step.',label:'03 / Browser action',heading:'A permitted action still needs a result.',summary:'In the intended runtime, the browser adapter would execute the allowed click and return a fresh observation. This illustration simulates that transition locally.',beforeLabel:'Allowed step',before:'Open the observed Pricing link.',afterLabel:'Execution record',after:'This is a scripted example. Use the example action button to see the simulated result.'},
{title:'Check the outcome, not just the click.',label:'04 / Verification',heading:'The page must show the information the task needs.',summary:'The fictional pricing page shows a monthly price and what it includes. That observation supports the task result. If the page did not load, the run should not report success.',beforeLabel:'New page observation',before:'The fictional pricing page shows a Starter plan at $19 per month.',afterLabel:'Verification result',after:'Pricing found in this example. No purchase or form submission occurred.'}
];
const get=id=>document.getElementById(id);const buttons=[...document.querySelectorAll('[data-goal]')];let selected=0,inspected=false,played=false;
function render(){const step=steps[selected];get('workflow-preview').dataset.stage=String(selected);get('workflow-preview').dataset.restarted=String(played);get('owner-status').textContent='Stage: '+['Observe','Propose','Act','Verify'][selected];get('checkpoint-status').textContent=played?'Example action recorded':'Example ready';for(const[id,value]of [['goal-title',step.title],['change-label',step.label],['change-title',step.heading],['change-summary',step.summary],['before-label',step.beforeLabel],['before-text',step.before],['after-label',step.afterLabel],['after-text',step.after]])get(id).textContent=value;
buttons.forEach((b,i)=>b.setAttribute('aria-pressed',String(i===selected)));get('inspect-change').setAttribute('aria-expanded',String(inspected));get('inspect-change').textContent=inspected?'Hide this step':'Inspect this step ↗';get('source-placeholder').hidden=inspected;get('source-before').hidden=!inspected;get('source-after').hidden=!inspected;get('save-step').setAttribute('aria-pressed',String(played));get('save-step').textContent=played?'Reset the example':'Play the example action';}
function move(){if(!window.matchMedia('(prefers-reduced-motion: reduce)').matches)get('change-card').animate([{transform:'translateY(6px)'},{transform:'translateY(0)'}],{duration:380,easing:'cubic-bezier(.22,1,.36,1)'});}
buttons.forEach((b,i)=>{b.addEventListener('click',()=>{selected=i;inspected=false;render();move();get('preview-status').textContent=`Illustrative stage: ${b.textContent.trim()}.`;});b.addEventListener('keydown',event=>{if(!['ArrowDown','ArrowUp','ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();const next=event.key==='Home'?0:event.key==='End'?buttons.length-1:(i+(['ArrowDown','ArrowRight'].includes(event.key)?1:-1)+buttons.length)%buttons.length;buttons[next].focus();buttons[next].click();});});
get('inspect-change').addEventListener('click',()=>{inspected=!inspected;render();get('preview-status').textContent=inspected?'Illustrative observation and action record shown.':'Step inspection closed.';});
get('save-step').addEventListener('click',()=>{played=!played;selected=played?3:0;inspected=played;render();move();get('preview-status').textContent=played?'Example only: the permitted navigation produced a fictional pricing observation. No website or model was contacted.':'Example reset to its initial observation.';});render();
})();
